import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Fish implements Comparable<Fish> {
    String name;
    int weight;

    Fish(String name, int weight) {
        this.name = name;
        this.weight = weight;
    }

    public int compareTo(Fish other) {
        return other.weight - this.weight;
    }

    public String toString() {
        return name + "(" + weight + ")";
    }
}

public class Main {
    public static void main(String[] args) {
        List<Fish> pond = new ArrayList<>();
        pond.add(new Fish("小橘", 5));
        pond.add(new Fish("煤球", 2));
        pond.add(new Fish("狸花", 8));

        Collections.sort(pond);
        System.out.println(pond);
        System.out.println("打头的是 " + pond.get(0));
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

class Fish {
    String name;

    Fish(String name) {
        this.name = name;
    }

    public String toString() {
        return name;
    }
}

class ShortFirst implements Comparator<Fish> {
    public int compare(Fish a, Fish b) {
        return a.name.length() - b.name.length();
    }
}

public class Main {
    public static void main(String[] args) {
        List<Fish> pond = new ArrayList<>();
        pond.add(new Fish("狸花猫猫"));
        pond.add(new Fish("小橘"));
        pond.add(new Fish("煤球球"));

        pond.sort(new ShortFirst());
        System.out.println(pond);
    }
}
